{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Surveillance Data",
    "url": "http://localhost:7807",
    "widgets_json": {
      "surveillance_cases_table": {
        "name": "Surveillance Cases Table",
        "description": "Open surveillance cases by severity.",
        "endpoint": "/surveillance-cases-table",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "case_id",
            "type": "text",
            "label": "Case Id",
            "value": "C-1042",
            "description": "Surveillance Cases Table focus field."
          }
        ],
        "data": {
          "defaultSymbol": "case_id",
          "table": {
            "columnsDefs": [
              {
                "field": "age_days",
                "headerName": "Age Days",
                "cellDataType": "number"
              },
              {
                "field": "case_id",
                "headerName": "Case Id",
                "cellDataType": "text"
              },
              {
                "field": "desk",
                "headerName": "Desk",
                "cellDataType": "text"
              },
              {
                "field": "severity",
                "headerName": "Severity",
                "cellDataType": "text"
              }
            ]
          }
        }
      },
      "alert_metric": {
        "name": "Open Alerts",
        "description": "Open alert count.",
        "endpoint": "/alert-count",
        "type": "metric",
        "gridData": {
          "w": 5,
          "h": 4
        }
      }
    },
    "apps_json": [
      {
        "name": "Compliance Surveillance",
        "description": "Surveillance cases and alert posture.",
        "tabs": {
          "cases": {
            "id": "cases",
            "name": "Cases",
            "layout": [
              {
                "i": "surveillance_cases_table",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "posture": {
            "id": "posture",
            "name": "Posture",
            "layout": [
              {
                "i": "alert_metric",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        }
      }
    ]
  }
}

